INSERT INTO recurring (counterparty_id, contract_id, cadence, typical_amount, amount_min, amount_max, first_seen, last_seen, occurrence_count, source) SELECT ct.counterparty_id, ct.id, 'irregular', m.typical_amount, m.amount_min, m.amount_max, m.first_seen, m.last_seen, m.occurrence_count, 'auto' FROM ( SELECT COALESCE(al.canonical_counterparty_id, own.id) AS effective_cp, CASE WHEN t.attributed_name IS NOT NULL THEN 'attributed' ELSE t.mandate_id END AS mandate_id, percentile_cont(0.5) WITHIN GROUP (ORDER BY t.amount) AS typical_amount, min(t.amount) AS amount_min, max(t.amount) AS amount_max, min(t.booking_date) AS first_seen, max(t.booking_date) AS last_seen, count(*) AS occurrence_count FROM transactions t LEFT JOIN counterparty_alias al ON al.identity_type = CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' END AND al.identity_value = CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id END LEFT JOIN counterparties own ON own.identity_type = CASE WHEN t.attributed_name IS NOT NULL THEN 'name' WHEN t.creditor_id IS NOT NULL THEN 'creditor_id' END AND own.identity_value = CASE WHEN t.attributed_name IS NOT NULL THEN upper(trim(regexp_replace(normalize(t.attributed_name, NFC), '\s+', ' ', 'g'))) WHEN t.creditor_id IS NOT NULL THEN t.creditor_id END WHERE t.split_parent_content_hash IS NULL AND (t.attributed_name IS NOT NULL OR (t.creditor_id IS NOT NULL AND t.mandate_id IS NOT NULL)) AND COALESCE(al.canonical_counterparty_id, own.id) IS NOT NULL GROUP BY 1, 2 ) m JOIN contracts ct ON ct.counterparty_id = m.effective_cp AND ct.mandate_id = m.mandate_id WHERE ct.mandate_id IS NOT NULL ON CONFLICT (counterparty_id, contract_id) DO UPDATE SET typical_amount = EXCLUDED.typical_amount, amount_min = EXCLUDED.amount_min, amount_max = EXCLUDED.amount_max, first_seen = EXCLUDED.first_seen, last_seen = EXCLUDED.last_seen, occurrence_count = EXCLUDED.occurrence_count, source = recurring.source
